<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { LogInfo as WailsLogInfo } from '@wails/runtime/runtime';
	import PageLayout from '$components/PageLayout.svelte';

	// Safe logging wrapper - works in both Wails and dev mode
	function logInfo(msg: string): void {
		try { WailsLogInfo(msg); } catch { /* dev mode: no Wails runtime */ }
	}
	import { userAccountData } from '$lib/state.svelte';
	import { validateUserAccount } from '$lib/validate';

	let username = $state('');
	let password = $state('');
	let confirmPassword = $state('');
	let usernameTouched = $state(false);
	let passwordTouched = $state(false);
	let confirmPasswordTouched = $state(false);

	const errors = $derived(
		validateUserAccount(username, password, confirmPassword, {
			usernameTouched,
			passwordTouched,
			confirmPasswordTouched,
		})
	);

	// Sync to store when requested (before validation)
	$effect(() => {
		const handler = () => {
			userAccountData.username = username;
			userAccountData.password = password;
			userAccountData.confirmPassword = confirmPassword;
			logInfo(`[UserAccountPage] Syncing to store for validation`);
		};
		document.addEventListener('sync-to-store', handler);
		return () => document.removeEventListener('sync-to-store', handler);
	});

	// Log after backend confirms
	$effect(() => {
		const handler = () => {
			logInfo(`[UserAccountPage] Backend confirmed, data is valid`);
		};
		document.addEventListener('backend-confirmed', handler);
		return () => document.removeEventListener('backend-confirmed', handler);
	});

	function handleBlur(field: 'username' | 'password' | 'confirmPassword'): void {
		switch (field) {
			case 'username': usernameTouched = true; break;
			case 'password': passwordTouched = true; break;
			case 'confirmPassword': confirmPasswordTouched = true; break;
		}
	}

	// Log when leaving the page
	$effect(() => {
		const handler = () => {
			logInfo(`[UserAccountPage] username: ${username}, password: ${password}`);
		};
		document.addEventListener('page-leave', handler);
		return () => document.removeEventListener('page-leave', handler);
	});
</script>

<PageLayout title="Create User Account">
	<form class="form" onsubmit={(e) => e.preventDefault()}>
		<div class="field">
			<label for="username">Username</label>
			<input
				id="username"
				type="text"
				class={['line-edit', { 'line-edit--error': !!errors.username }]}
				placeholder="Enter username"
				bind:value={username}
				onblur={() => handleBlur('username')}
			/>
			<span class="error" class:visible={!!errors.username}>{errors.username}</span>
		</div>

		<div class="field">
			<label for="password">Password</label>
			<input
				id="password"
				type="password"
				class={['line-edit', { 'line-edit--error': !!errors.password }]}
				placeholder="Enter password"
				bind:value={password}
				onblur={() => handleBlur('password')}
			/>
			<span class="error" class:visible={!!errors.password}>{errors.password}</span>
		</div>

		<div class="field">
			<label for="confirmPassword">Confirm Password</label>
			<input
				id="confirmPassword"
				type="password"
				class={['line-edit', { 'line-edit--error': !!errors.confirmPassword }]}
				placeholder="Confirm password"
				bind:value={confirmPassword}
				onblur={() => handleBlur('confirmPassword')}
			/>
			<span class="error" class:visible={!!errors.confirmPassword}>{errors.confirmPassword}</span>
		</div>
	</form>
</PageLayout>

